# F06 reviewer-requested experiments: 5,000 TF-IDF features. One Kaggle cell.
# Original archived F06 architecture; frozen 25,881-article split; all five seeds.
# Four controls: W0_S1, W1_S0, W0_S0, NO_ATTENTION_W1_S1.
# DO NOT change CSV or seeds; original F06 W1_S1 is ALREADY trained and is not repeated.
# Selected T4 x2 recommended; also works on one CUDA GPU.
import os
# Select account without changing model or fixed split; three independent
# Kaggle runs cover the five seeds without duplicate training.
_ACCOUNT = int(os.environ.get('HYS_CF_ACCOUNT', '1'))
_SEED_GROUPS = {1: [42, 2026], 2: [3407, 123], 3: [777]}
if _ACCOUNT not in _SEED_GROUPS:
    raise ValueError('HYS_CF_ACCOUNT must be 1, 2, or 3')
OPTIONS = {
    'MODE': 'RUN', 'ACCOUNT': _ACCOUNT,
    'DATA_CSV': '/kaggle/input/datasets/gurpreetsinghsidhu/newsdataset/updated_5000n (2).csv',
    'OUTPUT_DIR': f'/kaggle/working/F06_Pending_Review_Account_{_ACCOUNT}',
    'RUN_SEEDS': _SEED_GROUPS[_ACCOUNT],
    'MAX_RUNTIME_HOURS': 11.0,
    'KEEP_COMPLETED_OPTIMIZER_STATE': False,
    'INSTALL_MATCHING_ENVIRONMENT': True,
}

PAYLOAD = {'training_engine.py': {'sha256': 'c406c20b97ed8bbd8d68c750f6f47614ff3cb1ef00d82975f57e801e0a3c3ae2', 'payload': ''}, 'fusion_extension.py': {'sha256': '49bd79d278bea874503d398b5b91bcbb16a2bda4b8579e89e5abf06b4e62eb54', 'payload': ''}, 'ablation_driver.py': {'sha256': '6f3cfc9b2c4605357251dd06d3244d177d759d313af052a76bb75afb9cbc8364', 'payload': ''}}

import os,sys,time,json,hashlib,base64,zlib,subprocess,signal,fcntl,importlib.metadata
from pathlib import Path
os.environ['KERAS_BACKEND']='tensorflow'
os.environ.setdefault('TF_CPP_MIN_LOG_LEVEL','2')
os.environ.setdefault('TF_DETERMINISTIC_OPS','1')
os.environ.setdefault('CUBLAS_WORKSPACE_CONFIG',':4096:8')
os.environ.setdefault('PYTHONHASHSEED','42')
os.environ.setdefault('TOKENIZERS_PARALLELISM','false')

def _check_environment():
    required={'numpy':'2.1.3','pandas':'2.3.3','scipy':'1.15.3','scikit-learn':'1.6.1',
              'tensorflow':'2.20.0','keras':'3.13.2'}
    missing=[]
    for pkg,version in required.items():
        try:now=importlib.metadata.version(pkg)
        except importlib.metadata.PackageNotFoundError:now=None
        if now!=version:missing.append(pkg+'=='+version)
    try:importlib.metadata.version('matplotlib')
    except importlib.metadata.PackageNotFoundError:missing.append('matplotlib')
    if missing:
        if not OPTIONS['INSTALL_MATCHING_ENVIRONMENT']:
            raise RuntimeError('Required versions missing: '+', '.join(missing))
        print('Installing matching research environment:',missing,flush=True)
        subprocess.run([sys.executable,'-m','pip','install','--quiet','--disable-pip-version-check',*missing],check=True)
    for pkg,version in required.items():
        if importlib.metadata.version(pkg)!=version:raise RuntimeError('Version mismatch: '+pkg)

def _run():
    if OPTIONS['RUN_SEEDS'] not in ([42,2026],[3407,123],[777]):
        raise ValueError('The three account seed assignments must remain 42/2026, 3407/123, and 777')
    if OPTIONS['MODE'] not in ('RUN','REPORT_ONLY'):raise ValueError('MODE must be RUN or REPORT_ONLY')
    _check_environment()
    folder=Path(OPTIONS['OUTPUT_DIR']);folder.mkdir(parents=True,exist_ok=True)
    with (folder/'.onecell.lock').open('a+') as lk:
        try:fcntl.flock(lk,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:raise RuntimeError('Another worker already uses this output folder')
        runtime=folder/'runtime';runtime.mkdir(exist_ok=True)
        for name,entry in PAYLOAD.items():
            raw=zlib.decompress(base64.b64decode(entry['payload']))
            if hashlib.sha256(raw).hexdigest()!=entry['sha256']:raise RuntimeError('Corrupt embedded code: '+name)
            dest=runtime/name
            if dest.exists() and hashlib.sha256(dest.read_bytes()).hexdigest()!=entry['sha256']:
                raise RuntimeError('Existing runtime source differs; change OUTPUT_DIR only for a new experiment')
            dest.write_bytes(raw)
        args=dict(OPTIONS,STARTED_AT=time.time(),ENGINE_SHA256=PAYLOAD['training_engine.py']['sha256'],
                  EXT_SHA256=PAYLOAD['fusion_extension.py']['sha256'])
        optionsfile=runtime/'options.json';optionsfile.write_text(json.dumps(args,indent=2))
        process=subprocess.Popen([sys.executable,str(runtime/'ablation_driver.py'),'--settings',str(optionsfile)],
            stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1,start_new_session=True)
        try:
            for line in process.stdout:print(line,end='',flush=True)
            code=process.wait()
        except KeyboardInterrupt:
            os.killpg(process.pid,signal.SIGINT)
            for line in process.stdout:print(line,end='',flush=True)
            code=process.wait()
        print('COMPLETE trained model folder:',folder,flush=True)
        print('RESULTS-ONLY ZIP:',folder.parent/(folder.name+'_RESULTS_ONLY.zip'),flush=True)
        if code not in (0,75):raise RuntimeError('An experiment failed: see RUN_ERROR.json and worker logs. Completed fits are retained.')
        if code==75:print('PARTIAL: persist the COMPLETE native folder as Kaggle Dataset for restarting.',flush=True)
_run()
